'use strict';
const fs=require('node:fs'),path=require('node:path'),vm=require('node:vm'),http=require('node:http');
const root=path.resolve(__dirname,'../..'),html=fs.readFileSync(path.join(root,'public/financial-dashboard.html'),'utf8');
function productionFunction(name){const start=html.indexOf('function '+name+'(');if(start<0)throw Error(name);let source='';for(const line of html.slice(start).split(/\r?\n/)){source+=line+'\n';try{new vm.Script(source);return source;}catch(error){if(!(error instanceof SyntaxError))throw error;}}throw Error('Invalid function '+name);}
const confirmation=html.slice(html.indexOf('let approvalSubmitting=false,approvalTrigger=null;'),html.indexOf('function closeAll()',html.indexOf('let approvalSubmitting=false,approvalTrigger=null;')));
const fixtures=[['AP-001','Pembelian perlengkapan operasional dan bahan pembersih untuk kebutuhan harian cabang','Unit Utama','Rp 1.250.000','Menunggu otorisasi Owner','PENDING','warn','txn-a','24 Okt 2026, 09.00 WIB'],['AP-002','Penggantian alat pompa <img src=x onerror=alert(1)>','Unit Kedua','Rp 750.000','Menunggu otorisasi Owner','PENDING','warn','txn-b','24 Okt 2026, 10.00 WIB']];
function page(url){
 const mode=url.searchParams.get('mode')||'empty',theme=url.searchParams.get('theme')||'light',branch=url.searchParams.get('branch')||'all';
 const styles=[...html.matchAll(/<style\b[^>]*>[\s\S]*?<\/style>/g)].map(m=>m[0]).join(''),items=mode==='empty'?[]:fixtures;
 const script=productionFunction('escHtml')+productionFunction('pageHead')+productionFunction('visibleApprovals')+productionFunction('approvals')+productionFunction('bindApprovals')+confirmation;
 return '<!doctype html><html lang="id" data-theme="'+(theme==='dark'?'dark':'light')+'"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Approval UI · Synthetic QA</title>'+styles+'<style>body{margin:0}#content{padding:26px;min-width:0}.qa-nav{padding:16px 26px;border-bottom:1px solid var(--line);color:var(--ink)}#drawerBody{padding:20px}.approval-workspace .card p{max-width:none}@media(max-width:600px){#content{padding:18px}}</style></head><body><header class="qa-nav">SiPeKA · Approval Center · Pengujian</header><main id="content"></main><div class="overlay" id="overlay"></div><div class="modal" id="modal" role="dialog" aria-modal="true" aria-labelledby="modalTitle" aria-describedby="modalCopy"><h2 id="modalTitle"></h2><p id="modalCopy"></p><div class="modal-actions"><button class="btn" data-close>Batal</button><button class="btn primary" id="modalConfirm">Konfirmasi</button></div></div><aside class="drawer" id="drawer"><div id="drawerBody"></div></aside><div id="toast" role="status"></div><script>'+fs.readFileSync(path.join(root,'public/lucide-icons.js'),'utf8')+'</script><script>let role='+JSON.stringify(mode==='staff'?'staff':'owner')+',selectedBranch='+JSON.stringify(branch)+',approvalItems='+JSON.stringify(items).replace(/</g,'\\u003c')+',pendingAction="",pendingTxId=null;const content=document.querySelector("#content"),modal=document.querySelector("#modal"),modalTitle=document.querySelector("#modalTitle"),modalCopy=document.querySelector("#modalCopy"),modalConfirm=document.querySelector("#modalConfirm"),overlay=document.querySelector("#overlay");const transactions=approvalItems.map(r=>[null,r[1],r[2],null,null,r[3],null,"Pending",null,r[7]]);window.calls=[];window.refreshes=0;window.failApproval=false;window.holdApproval=false;window.SipekaCurrentUser={id:"qa",role:role.toUpperCase()};const icon=k=>SipekaIcons.render(k);function scopeName(){return selectedBranch==="all"?"All Branches":selectedBranch;}function showToast(message){document.querySelector("#toast").textContent=message;}function closeAll(){modal.classList.remove("open");overlay.classList.remove("show");}function openTransaction(index){window.openedTransaction=index;document.querySelector("#drawerBody").textContent=transactions[index][1];}window.SipekaAuth={async api(url,options){window.calls.push({url,options});if(window.holdApproval)await new Promise(resolve=>window.releaseApproval=resolve);if(window.failApproval)throw Error("Synthetic failure");},async bootstrap(){window.refreshes++;}};'+script+'content.innerHTML=approvals();bindApprovals();content.querySelectorAll("[data-approval]").forEach(b=>b.onclick=()=>confirmAction(b.dataset.approval,b.dataset.approvalId,b.dataset.approvalTxid));document.querySelector("[data-close]").onclick=closeAll;overlay.onclick=closeAll;</script></body></html>';
}
function createServer(){return http.createServer((req,res)=>{res.setHeader('Content-Type','text/html; charset=utf-8');res.end(page(new URL(req.url,'http://localhost')));});}
module.exports={createServer,fixtures,productionFunction};
if(require.main===module)createServer().listen(5440,'127.0.0.1',()=>console.log('Synthetic Approval UI: http://127.0.0.1:5440/'));
